describe('S-2 supporting: ceilDiv and exactness', () => {
  it('ceilDiv rounds up only when there is a remainder', () => {
    expect(ceilDiv(700, 1000)).toBe(1);
    expect(ceilDiv(1000, 1000)).toBe(1);
    expect(ceilDiv(1001, 1000)).toBe(2);
    expect(ceilDiv(0, 1000)).toBe(0);
    expect(ceilDiv(100_000_000_000, 1000)).toBe(100_000_000);
  });

  it('the widest gaps stay exact safe integers', () => {
    expect(gap(0, 100_000_000, 1000)).toEqual({ kind: 'short', h: 100_000_000 });
    expect(gapText(gap(0, 100_000_000, 1000))).toBe('1,000,000 marks short of the pass mark');
  });
});

describe('S-2 supporting: no gap line outside the result state', () => {
  it.each<[string, string, string]>([
    ['', '', '70'],
    ['17.5', '', '70'],
    ['17.5', '23', ''],
    ['abc', '23', '70'],
    ['23.5', '23', '70'],
  ])('%j of %j at %j has no gap text', (earned, total, pass) => {
    const model = vm(earned, total, pass);
    expect(model.state).not.toBe('result');
    expect(model).not.toHaveProperty('gapText');
    expect(JSON.stringify(model)).not.toMatch(/(short of|above|on) the pass mark/);
  });

  it('every gap kind gives non-blank text without NaN, Infinity or undefined', () => {
    const gaps: Gap[] = [{ kind: 'exact' }, { kind: 'aboveTiny' }, { kind: 'short', h: 1 }, { kind: 'above', h: 100_000_000 }];
    for (const g of gaps) {
      const text = gapText(g);
      expect(text.trim().length).toBeGreaterThan(0);
      for (const bad of ['NaN', 'Infinity', 'undefined', '{n}']) expect(text).not.toContain(bad);
    }
  });
});
import type { Locator, Page } from '@playwright/test';
import { test, expect } from './fixtures';
import { MESSAGES } from '../../src/messages';

// S-2 Marks short of or above the pass mark (test-plan.md E-S2.1..E-S2.8).
// Gap strings are quoted exactly from the ACs; verdict words come from messages.ts (M-4, M-5).

const PASS = MESSAGES['M-4'];
const FAIL = MESSAGES['M-5'];

type Tone = 'pass' | 'fail';

interface Card {
  earned: Locator;
  total: Locator;
  pass: Locator;
  result: Locator;
  score: Locator;
  verdict: Locator;
  gap: Locator;
  status: Locator;
}

function card(page: Page): Card {
  const result = page.getByRole('region', { name: MESSAGES['M-39'] });
  return {
    earned: page.getByLabel(MESSAGES['M-34'], { exact: true }),
    total: page.getByLabel(MESSAGES['M-35'], { exact: true }),
    pass: page.getByLabel(MESSAGES['M-36'] + MESSAGES['M-37'], { exact: true }),
    result,
    score: result.locator('.score'),
    verdict: result.locator('.verdict'),
    gap: result.locator('.gap'),
    status: page.getByRole('status'),
  };
}

async function enter(c: Card, earned: string, total: string, pass?: string): Promise<void> {
  if (pass !== undefined) await c.pass.fill(pass);
  await c.total.fill(total);
  await c.earned.fill(earned);
}

/** The gap line text, plus its decorative icon (never colour alone: the words carry the meaning). */
async function expectGap(c: Card, text: string, tone: Tone): Promise<void> {
  await expect(c.gap).toHaveText(text);
  const icon = c.gap.locator('svg');
  await expect(icon).toHaveAttribute('aria-hidden', 'true');
  await expect(icon).toHaveClass(new RegExp(`gap-icon--${tone}`));
}

async function expectVerdict(c: Card, score: string, verdict: string): Promise<void> {
  await expect(c.score).toHaveText(score);
  await expect(c.verdict).toHaveText(verdict);
}

